// ─────────────────────────────────────────────────────────────────────────────
// AllComponents — directory of every Tkx* component grouped by family.
//
// Click behaviour:
//   - If the component has a published docs page at /components/<slug>/
//     (Astro Starlight, autogenerated from docs-site/src/content/docs/
//     components/*.mdx), the chip is a real <a> to that URL. The reader
//     gets to the docs immediately — Props table, live demo, examples.
//   - Otherwise (component exists in the library but no MDX page yet),
//     the chip falls back to the RequestAccessDialog. That signals an
//     intent to the maintainer to prioritise writing docs for that one.
//
// The DOCUMENTED_SLUGS set below is the source of truth — keep it in
// sync with `ls docs-site/src/content/docs/components/*.mdx`. A future
// follow-up could replace this with a build-time Vite glob to remove
// the manual sync. Listed inline here so the click-handler branch is
// pure, no async, no import.meta.glob complexity in this commit.
// ─────────────────────────────────────────────────────────────────────────────

import { useState } from 'react';
import { RequestAccessDialog, type RequestTarget } from '../RequestAccessDialog';

