const TOTAL = GROUPS.reduce((n, g) => n + g.components.length, 0);

// Map group title hint → package name (used to pre-fill the request issue)
function pkgForGroup(title: string): string {
  if (/3D \/ 360°|tekivex-3d/i.test(title)) return 'tekivex-3d';
  return 'tekivex-ui';
}

export function AllComponents() {
  const [requested, setRequested] = useState<RequestTarget | null>(null);
  return (
    <section
      id="components"
      style={{ padding: '88px 24px 48px', maxWidth: 1280, margin: '0 auto' }}
    >
      <header style={{ textAlign: 'center', marginBottom: 40 }}>
        <h2
          style={{
            fontSize: 'clamp(1.8rem, 4vw, 2.8rem)',
            fontWeight: 800,
            letterSpacing: '-0.03em',
            margin: '0 0 12px',
          }}
        >
          Browse all <span className="tk-gradient-text">{TOTAL}</span> components
        </h2>
        <p style={{ color: '#1f2937', maxWidth: 660, margin: '0 auto', fontSize: 16, lineHeight: 1.65 }}>
          Click any component below to request access — we publish the latest
          source to npm on demand and email setup instructions back. Browse the
          full live catalog at{' '}
          <a href="/playground/" style={{ color: '#0f766e', fontWeight: 600 }}>
            /playground/
          </a>{' '}
          or storybook-style controls at{' '}
          <a href="/book/" style={{ color: '#0f766e', fontWeight: 600 }}>
            /book/
          </a>
          .
        </p>
      </header>

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
          gap: 16,
        }}
      >
        {GROUPS.map((g) => (
          <div
            key={g.title}
            style={{
              padding: 22,
              borderRadius: 14,
              border: '1px solid #e5e7eb',
              background: '#ffffff',
              boxShadow:
                '0 1px 2px rgba(0,0,0,0.04), 0 1px 3px rgba(0,0,0,0.06)',
            }}
          >
            <header
              style={{
                display: 'flex',
                gap: 10,
                alignItems: 'center',
                marginBottom: 4,
              }}
            >
              <span style={{ fontSize: 22 }} aria-hidden="true">
                {g.emoji}
              </span>
              <h3
                style={{
                  margin: 0,
                  fontSize: 16,
                  fontWeight: 700,
                  color: '#0a0a0f',
                  letterSpacing: '-0.01em',
                }}
              >
                {g.title}
              </h3>
              <span
                style={{
                  marginLeft: 'auto',
                  color: '#6b7280',
                  fontSize: 12,
                  fontFamily: 'monospace',
                }}
              >
                {g.components.length}
              </span>
            </header>
            <p style={{ color: '#4b5563', fontSize: 12, margin: '0 0 14px' }}>{g.desc}</p>

            <ul
              style={{
                listStyle: 'none',
                padding: 0,
                margin: 0,
                display: 'flex',
                flexWrap: 'wrap',
                gap: 6,
              }}
            >
              {g.components.map((c) => {
                // Shared chip styling — used by both the <a> and the fallback <button>.
                const chipStyle: React.CSSProperties = {
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 4,
                  padding: '4px 10px',
                  borderRadius: 6,
                  background: '#fafbfc',
                  border: '1px solid #e5e7eb',
                  color: '#1f2937',
                  fontSize: 12,
                  fontWeight: 500,
                  transition: 'all 0.15s',
                  cursor: 'pointer',
                  fontFamily: 'inherit',
                  textDecoration: 'none',
                };
                const handleEnter = (e: React.MouseEvent<HTMLElement>) => {
                  e.currentTarget.style.color = '#0f766e';
                  e.currentTarget.style.borderColor = '#99f6e4';
                  e.currentTarget.style.background = '#f0fdfa';
                };
                const handleLeave = (e: React.MouseEvent<HTMLElement>) => {
                  e.currentTarget.style.color = '#1f2937';
                  e.currentTarget.style.borderColor = '#e5e7eb';
                  e.currentTarget.style.background = '#fafbfc';
                };
                const chipChildren = (
                  <>
                    {c.name}
                    {c.isNew && (
                      <span style={{ fontSize: 9, color: '#0f766e', fontWeight: 700, letterSpacing: '0.05em' }}>
                        NEW
                      </span>
                    )}
                  </>
                );

                return (
                  <li key={c.slug}>
                    {DOCUMENTED_SLUGS.has(c.slug) ? (
                      // Real docs page exists — link to it directly. No JS, no modal.
                      <a
                        href={`/components/${c.slug}/`}
                        style={chipStyle}
                        onMouseEnter={handleEnter}
                        onMouseLeave={handleLeave}
                      >
                        {chipChildren}
                      </a>
                    ) : (
                      // No docs page yet — open the request-access dialog so the
                      // maintainer sees demand for docs/source of this component.
                      <button
                        type="button"
                        onClick={() =>
                          setRequested({
                            name: c.name.startsWith('Tkx') ? c.name : `Tkx${c.name}`,
                            slug: c.slug,
                            pkg: pkgForGroup(g.title),
                          })
                        }
                        style={chipStyle}
                        onMouseEnter={handleEnter}
                        onMouseLeave={handleLeave}
                        title="Docs page not published yet — click to request"
                      >
                        {chipChildren}
                      </button>
                    )}
                  </li>
                );
              })}
            </ul>
          </div>
        ))}
      </div>

      <div
        style={{
          textAlign: 'center',
          marginTop: 40,
          display: 'flex',
          justifyContent: 'center',
          gap: 12,
          flexWrap: 'wrap',
        }}
      >
        <a
          href="/playground/"
          style={{
            padding: '12px 24px',
            background: '#0d9488',
            color: '#ffffff',
            fontWeight: 700,
            borderRadius: 999,
            fontSize: 14,
            minHeight: 44,
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
          }}
        >
          🎮 Open the playground →
        </a>
        <a
          href="/book/"
          style={{
            padding: '12px 24px',
            background: '#ffffff',
            border: '1px solid #e5e7eb',
            color: '#1f2937',
            fontWeight: 700,
            borderRadius: 999,
            fontSize: 14,
            minHeight: 44,
            display: 'inline-flex',
            alignItems: 'center',
            gap: 8,
          }}
        >
          📖 Open the catalog →
        </a>
      </div>

      <RequestAccessDialog target={requested} onClose={() => setRequested(null)} />
    </section>
  );
}
